CREATE TABLE IF NOT EXISTS vehicles (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, vin text UNIQUE NOT NULL, model text NOT NULL, color text, year integer, price numeric(18,2) NOT NULL CHECK(price>=0), status text NOT NULL DEFAULT 'available' CHECK(status IN ('available','reserved','sold')));
CREATE TABLE IF NOT EXISTS customers (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, full_name text NOT NULL, passport text, jshshir text CHECK(jshshir ~ '^[0-9]{14}$'), phone text, address text);
CREATE TABLE IF NOT EXISTS contracts (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, vehicle_id bigint NOT NULL REFERENCES vehicles(id), customer_id bigint NOT NULL REFERENCES customers(id), total numeric(18,2) NOT NULL CHECK(total>=0), net numeric(18,2) GENERATED ALWAYS AS (round(total/1.12,2)) STORED, vat numeric(18,2) GENERATED ALWAYS AS (total-round(total/1.12,2)) STORED, created_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'confirmed' CHECK(status IN ('confirmed','cancelled')));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_sale ON contracts(vehicle_id) WHERE status='confirmed';
